fn fibonacci(n: usize) -> Vec<i32> {
    // Pre-allocate a vector with capacity n
    let mut fibs = Vec::with_capacity(n);
    
    // Handle the first two base cases
    // According to the problem statement, n >= 2,
    // but we'll handle smaller n gracefully anyway.
    if n >= 1 {
        fibs.push(0);
    }
    if n >= 2 {
        fibs.push(1);
    }
    
    // Build the sequence up to n elements
    for i in 2..n {
        // Safe to add without overflow per problem guarantee
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }
    
    fibs
}

